CREATE TABLE IF NOT EXISTS system_message (id BIGINT PRIMARY KEY AUTO_INCREMENT, receiver_type VARCHAR(30) NOT NULL, receiver_account VARCHAR(200) NOT NULL, title VARCHAR(200) NOT NULL, content VARCHAR(1000) NOT NULL, booking_id BIGINT NULL, message_type VARCHAR(40) NOT NULL DEFAULT 'system', is_read TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_msg_receiver (receiver_type,receiver_account,is_read), INDEX idx_msg_booking (booking_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
